28	                existing.add(other.getMemberId());
29	            }
30	        }
31	        String memberId = base;
32	        for (int n = 2; existing.contains(memberId); n++) {
33	            memberId = base + "-" + n;
34	        }
35	        owner.setMemberId(memberId);
36	    }
